using System;using UnityEngine;
public sealed partial class IgniteChecks {
 void CustomSkinChecks(){
  var type=assembly.GetType("ChainsawPrototype.FlameBurntCorpse",true);var refresh=type.GetMethod("RefreshAppearance",All);Check(refresh!=null,"owned burn appearance can follow a delayed custom skin swap");if(refresh==null)return;
  var root=Make("CustomCorpse_Dead");var child=Make("CustomBody");child.transform.SetParent(root.transform,false);var renderer=child.AddComponent<SkinnedMeshRenderer>();var mesh=new Mesh();mesh.vertices=new[]{Vector3.zero,Vector3.right,Vector3.up};mesh.triangles=new[]{0,1,2};renderer.sharedMesh=mesh;
  var source=new Material(Shader.Find("Standard"));var later=new Material(Shader.Find("Sprites/Default"));var texture=new Texture2D(2,2);source.mainTexture=texture;later.mainTexture=texture;renderer.sharedMaterials=new[]{source,source};var burn=root.AddComponent(type);Call(burn,"ApplySkinFile",System.IO.Path.Combine(host,"lib/Flamethrower/BurntSkin.png"));var burnt=renderer.sharedMaterial.mainTexture;
  renderer.sharedMaterials=new[]{later,source};Call(burn,"LateUpdate");Check(renderer.sharedMaterial.mainTexture==burnt,"delayed custom skin swap is corrected in the same LateUpdate without a polling delay");refresh.Invoke(burn,null);var materials=renderer.sharedMaterials;
  Check(materials.Length==2&&materials[0].mainTexture==burnt&&materials[1].mainTexture==burnt,"delayed custom skin materials receive burn appearance in every slot");Check(renderer.sharedMesh==mesh&&materials[0].shader==later.shader,"custom corpse mesh and shader survive the burn refresh");Check(later.mainTexture==texture&&source.mainTexture==texture,"custom shared skin assets remain untouched");
  var prior=materials[0];for(int i=0;i<10;i++)refresh.Invoke(burn,null);Check(renderer.sharedMaterial==prior,"unchanged burnt materials are reused without repeated cloning");
  renderer.sharedMaterial=later;refresh.Invoke(burn,null);Check(renderer.sharedMaterial==prior,"repeated assignment of a shared custom skin reuses its owned burn clone");
  var order=(DefaultExecutionOrder)Attribute.GetCustomAttribute(type,typeof(DefaultExecutionOrder));Check(order!=null&&order.order>=30000,"owned corpse refresh runs late after ordinary custom skin LateUpdate work");
  var tick=(Action)Delegate.CreateDelegate(typeof(Action),burn,type.GetMethod("LateUpdate",All));var clock=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<10000;i++)tick();clock.Stop();Timing("TIMING: 10000 cached corpse material observations="+clock.Elapsed.TotalMilliseconds.ToString("F3")+" ms; isolated one-corpse fixture, not whole-game FPS");Check(renderer.sharedMaterial==prior,"steady-state frame observations retain the same owned material");
  var added=Make("LateCustomBody");added.transform.SetParent(root.transform,false);added.AddComponent<MeshRenderer>().sharedMaterial=later;Call(burn,"OnTransformChildrenChanged");refresh.Invoke(burn,null);Check(added.GetComponent<MeshRenderer>().sharedMaterial.mainTexture==burnt,"late attached custom body renderer also receives owned burn appearance");
  var neighbor=Make("UnburntCustomNeighbor");neighbor.AddComponent<MeshRenderer>().sharedMaterial=later;Check(neighbor.GetComponent<MeshRenderer>().sharedMaterial.mainTexture==texture,"unburnt custom skin neighbor is unchanged");DestroyImmediate(root);Check(source!=null&&later!=null&&texture!=null&&mesh!=null,"corpse cleanup preserves third party meshes materials and textures");DestroyImmediate(neighbor);DestroyImmediate(mesh);DestroyImmediate(source);DestroyImmediate(later);DestroyImmediate(texture);
 }
}
